"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import { useExperience } from "../../../engine/experienceStore";
import { getPlanetsArray, PlanetMetadata } from "../../../config/planetMetadata";
import WarpTransition from "../WarpTransition";

export default function PlanetCard() {
  const router = useRouter();
  const { mode, activePlanet, resetExperience } = useExperience();
  const [isWarping, setIsWarping] = useState(false);
  const isVisible = mode === "enter";

  // Resolve the full planet data to get correct route path
  const planetData = getPlanetsArray().find((p: PlanetMetadata) => p.id === activePlanet);
  const targetRoute = planetData?.routePath || "/";

  const handleEnterDomain = () => {
    setIsWarping(true);
    // WarpTransition handles the navigation delay
    setTimeout(() => {
      resetExperience();
      router.push(targetRoute);
    }, 800);
  };

  return (
    <AnimatePresence>
      {isVisible && (
        <motion.div
          initial={{ y: 200, opacity: 0, scale: 0.9, rotateX: 15 }}
          animate={{ y: 0, opacity: 1, scale: 1, rotateX: 0 }}
          exit={{ y: 200, opacity: 0, scale: 0.9, rotateX: -15 }}
          transition={{
            type: "spring",
            stiffness: 100,
            damping: 15,
          }}
          style={{
            position: "absolute",
            bottom: "8%",
            left: "50%",
            transform: "translateX(-50%)",
            width: "min(90vw, 480px)",
            padding: "2.5rem 2rem",
            background:
              "linear-gradient(145deg, rgba(5,20,35,0.7) 0%, rgba(0,5,10,0.85) 100%)",
            backdropFilter: "blur(24px)",
            WebkitBackdropFilter: "blur(24px)",
            borderRadius: "16px",
            border: "1px solid rgba(0,255,170,0.3)",
            boxShadow:
              "0 0 40px rgba(0,255,170,0.15), inset 0 0 20px rgba(0,200,255,0.1)",
            color: "white",
            zIndex: 100,
            textAlign: "center",
            overflow: "hidden",
          }}
        >
          {/* Accent Line */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: "10%",
              right: "10%",
              height: "2px",
              background:
                "linear-gradient(90deg, transparent, #00ffaa, transparent)",
            }}
          />

          {/* System Status */}
          <div
            style={{
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              gap: "8px",
              marginBottom: "16px",
              fontSize: "11px",
              letterSpacing: "3px",
              color: "#00ffaa",
              textTransform: "uppercase",
            }}
          >
            <motion.div
              animate={{ opacity: [1, 0.2, 1] }}
              transition={{ duration: 1.5, repeat: Infinity }}
              style={{
                width: "8px",
                height: "8px",
                borderRadius: "50%",
                backgroundColor: "#00ffaa",
                boxShadow: "0 0 10px #00ffaa",
              }}
            />
            System Active
          </div>

          {/* Planet Name */}
          <h2
            style={{
              margin: 0,
              fontSize: "2.5rem",
              textTransform: "uppercase",
              letterSpacing: "6px",
              fontWeight: 900,
              background:
                "linear-gradient(to right, #00ffaa, #00d4ff)",
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
              textShadow:
                "0px 0px 20px rgba(0,255,170,0.4)",
            }}
          >
            {activePlanet
              ? activePlanet.toUpperCase().replace("-", " ")
              : "UNKNOWN"}
          </h2>

          <p
            style={{
              opacity: 0.8,
              marginTop: "20px",
              lineHeight: "1.8",
              fontSize: "14px",
              color: "#c0e0ff",
            }}
          >
            ACCESSING SPATIAL DATA... EXPLORE THE CORE ARCHIVES AND LEGACY
            MODULES OF THIS SECTOR.
          </p>

          <motion.button
            whileHover={{
              scale: 1.05,
              backgroundColor: "rgba(0,255,170,0.1)",
              boxShadow: "0 0 20px rgba(0,255,170,0.4)",
            }}
            whileTap={{ scale: 0.95 }}
            style={{
              marginTop: "35px",
              padding: "14px 36px",
              borderRadius: "8px",
              background: "transparent",
              color: "#00ffaa",
              border: "1px solid #00ffaa",
              fontWeight: "bold",
              letterSpacing: "3px",
              cursor: "pointer",
              textTransform: "uppercase",
            }}
            onClick={handleEnterDomain}
          >
            Enter Domain
          </motion.button>

          {/* Warp transition overlay */}
          {isWarping && (
            <div
              style={{
                position: "fixed",
                inset: 0,
                zIndex: 99999,
                background: "white",
                animation: "fadeInOut 0.8s ease-in-out forwards",
              }}
            >
              <style>{`
                @keyframes fadeInOut {
                  0% { opacity: 0; }
                  50% { opacity: 1; }
                  100% { opacity: 0; }
                }
              `}</style>
            </div>
          )}
        </motion.div>
      )}
    </AnimatePresence>
  );
}